const dictionaries: Record<Language, Record<TranslationKey, string>> = { fr, en, pt, es };
const languageNames: Record<Language, string> = { fr: "Français", en: "English", pt: "Português", es: "Español" };

type I18nValue = { language: Language; setLanguage: (language: Language) => void; t: (key: TranslationKey) => string };
const I18nContext = createContext<I18nValue | null>(null);

export function I18nProvider({ children }: { children: React.ReactNode }) {
  const [language, setLanguage] = useState<Language>(() => {
    const saved = window.localStorage.getItem("stryker-language");
    return saved && ["fr", "en", "pt", "es"].includes(saved) ? saved as Language : "fr";
  });

  useEffect(() => {
    window.localStorage.setItem("stryker-language", language);
    document.documentElement.lang = language;
  }, [language]);

  const value = useMemo<I18nValue>(() => ({ language, setLanguage, t: (key) => dictionaries[language][key] }), [language]);
  return <I18nContext.Provider value={value}>{children}</I18nContext.Provider>;
}

export function useI18n() {
  const context = useContext(I18nContext);
  if (!context) throw new Error("useI18n must be used inside I18nProvider");
  return context;
}

export function LanguageSwitcher({ compact = false }: { compact?: boolean }) {
  const { language, setLanguage, t } = useI18n();
  return (
    <label className="inline-flex items-center gap-2 rounded-full border border-white/10 bg-white/5 px-2.5 py-1.5 text-[10px] font-bold text-white/70">
      <Globe2 className="h-3.5 w-3.5 text-[#d870c5]" />
      <span className="sr-only">{t("language.label")}</span>
      <select aria-label={t("language.label")} value={language} onChange={(event) => setLanguage(event.target.value as Language)} className={`bg-transparent text-white outline-none ${compact ? "max-w-20" : "max-w-28"}`}>
        {(Object.keys(languageNames) as Language[]).map((code) => <option key={code} value={code} className="bg-[#1a0717] text-white">{languageNames[code]}</option>)}
      </select>
    </label>
  );
}
